using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static ReportingConfiguration _reporting = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _reporting = new ReportingConfiguration(
            new DiskBasedReportingStorage(Path.Combine(context.TestRunResultsDirectory!, "eval-results")));
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    [DynamicData(nameof(GetScenarios), DynamicDataSourceType.Method)]
    public async Task EvaluateScenario(EvaluationScenario scenario)
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var response = await chatClient.GetResponseAsync(scenario.ChatMessages);
        var messages = new List<ChatMessage>(scenario.ChatMessages);
        messages.AddRange(response.Messages);

        await using var session = await _reporting.CreateScenarioRunAsync(scenario.Name);
        await session.EvaluateAsync(messages, scenario.Evaluators);

        foreach (var result in session.GetResults())
        {
            Assert.IsFalse(
                result.Value.Rating == EvaluationRating.Unacceptable,
                $"Evaluator '{result.Key}' rated response as unacceptable for scenario '{scenario.Name}'.");
        }
    }

    private static IEnumerable<object[]> GetScenarios()
        => Scenarios.All.Select(s => new object[] { s });
}

